import os
import tempfile
import pytest
from solution import FileUploadHandler

@pytest.fixture
def handler(tmp_path):
    return FileUploadHandler(str(tmp_path))

def test_valid_upload(handler, tmp_path):
    ok, result = handler.save_file('report.pdf', b'%PDF-1.4 content')
    assert ok is True
    assert os.path.exists(result)

def test_invalid_extension(handler):
    ok, result = handler.save_file('script.exe', b'MZ...')
    assert ok is False

def test_traversal_blocked(handler):
    ok, result = handler.validate_filename('../../../etc/passwd')
    assert ok is False

def test_traversal_encoded(handler):
    ok, result = handler.validate_filename('..%2F..%2Fetc%2Fpasswd')
    assert ok is False

def test_size_limit(handler):
    ok, result = handler.save_file('big.txt', b'x' * 20_000_000)
    assert ok is False

def test_empty_filename(handler):
    ok, result = handler.validate_filename('')
    assert ok is False

def test_dotfile(handler):
    ok, result = handler.validate_filename('.htaccess')
    assert ok is False
